<?php
declare(strict_types=1);

if($argc<2){fwrite(STDERR,"Usage: php bin/http-smoke.php PAY_xxx [username] [password]\n");exit(2);}
$root=dirname(__DIR__);$port=18092;$address="http://127.0.0.1:{$port}";$log='/private/tmp/cardpay-http-smoke.log';$process=proc_open([PHP_BINARY,'-S',"127.0.0.1:{$port}",'-t',$root.'/public',$root.'/public/router.php'],[['pipe','r'],['file',$log,'a'],['file',$log,'a']],$pipes,$root);if(!is_resource($process))throw new RuntimeException('Could not start PHP server.');
$cookie='/private/tmp/cardpay-http-smoke-cookie.txt';$request=static function(string$url,string$method='GET',array$data=[])use($cookie):array{$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_TIMEOUT=>5]);if($method==='POST')curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query($data));$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$size=(int)curl_getinfo($ch,CURLINFO_HEADER_SIZE);$error=curl_error($ch);curl_close($ch);if($raw===false)throw new RuntimeException($error);return[$status,substr($raw,$size),substr($raw,0,$size)];};
try{$ready=false;for($i=0;$i<20;$i++){usleep(100000);try{[$status]=$request($address.'/login');if($status===200){$ready=true;break;}}catch(Throwable){}}if(!$ready)throw new RuntimeException('HTTP server did not become ready.');[$status,$login]=$request($address.'/login');if($status!==200||!preg_match('/name="_csrf" value="([a-f0-9]+)"/',$login,$match))throw new RuntimeException('Login page failed.');[$status,,$headers]=$request($address.'/login','POST',['_csrf'=>$match[1],'username'=>$argv[2]??'admin','password'=>$argv[3]??'CardPay-QA-2026']);if($status!==302)throw new RuntimeException('Login action failed with '.$status);[$status,$dashboard]=$request($address.'/admin');if($status!==200||!str_contains($dashboard,'داشبورد'))throw new RuntimeException('Dashboard failed.');[$status,$payment]=$request($address.'/p/'.rawurlencode($argv[1]));if($status!==200||!str_contains($payment,'مبلغ نهایی قابل پرداخت'))throw new RuntimeException('Payment page failed.');[$status,$json]=$request($address.'/api/v1/public/payments/'.rawurlencode($argv[1]).'/status');$decoded=json_decode($json,true);if($status!==200||!($decoded['success']??false))throw new RuntimeException('Public status failed.');[$status,,$headers]=$request($address.'/assets/app.css');if($status!==200||!str_contains(strtolower($headers),'content-type: text/css'))throw new RuntimeException('Static asset failed.');echo"HTTP smoke test passed: login, dashboard, payment page, status and assets.\n";}finally{proc_terminate($process);proc_close($process);@unlink($cookie);}
